import "auction"
import "dns-utils"
import "errors"
import "messages"
import "storage"

contract DnsItem {
    author: "The Tolk Team"
    version: "1.0.0"
    description: "DNS NFT Item. Domain name with auction support"
    incomingMessages: AllowedItemMessage
    storage: ItemStorageInitialized
    storageAtDeployment: ItemStorageNotInitialized
}

type AllowedItemMessage =
    | TransferOwnership
    | EditContent
    | ChangeDnsRecord
    | ProcessGovernanceDecision
    | DnsRecordRelease
    | GetStaticData

type GovernanceDecision = GovernanceTransfer | GovernanceRelease

fun onInternalMessage(in: InMessage) {
    val loadingStorage = startLoadingDnsItemStorage();

    if (!loadingStorage.isInitialized()) {
        val uninitStorage = loadingStorage.parseNotInitialized();
        assert (
            in.senderAddress == uninitStorage.collectionAddress
        ) throw ERROR_NOT_FROM_COLLECTION;

        val initData = lazy ItemInitData.fromSlice(in.body);

        val now = blockchain.now();

        val seconds = now - AUCTION_START_TIME;
        var months = seconds / ONE_MONTH;
        if (months > 12) {
            months = 12;
        }

        val duration = AUCTION_START_DURATION -
        // check-disable-next-line divide-before-multiply
        (AUCTION_START_DURATION - AUCTION_END_DURATION) * months / 12;

        val auctionEndTime = now + duration;
        val initialContent: DnsRecords = [];

        val initStorage = ItemStorageInitialized {
            index: uninitStorage.index,
            collectionAddress: uninitStorage.collectionAddress,
            ownerAddress: null,
            content: initialContent.toCell(),
            domain: initData.domain,
            auction: AuctionState {
                maxBidAddress: initData.fromAddress,
                maxBidAmount: in.valueCoins,
                auctionEndTime,
            }.toCell(),
            lastFillUpTime: now,
        };

        initStorage.save();
        return;
    }

    var storage = loadingStorage.parseInitialized();

    if (in.senderAddress == storage.collectionAddress) {
        val initData = lazy ItemInitData.fromSlice(in.body);

        val returnMessage = createMessage({
            dest: initData.fromAddress,
            body: Op0WithQuery { queryId: blockchain.logicalTime() },
            bounce: false,
            value: 0,
        });
        returnMessage.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);

        return;
    }

    val unpackedAuction = storage.unpackAuction();
    val isAuctionNull = unpackedAuction.0;
    var auction = unpackedAuction.1;
    val isAuctionComplete = blockchain.now() > auction.auctionEndTime;

    if (in.body.isEmpty() || in.body.preloadUint(32) == 0) {
        processBidOrTopUp(
            in.senderAddress,
            in.valueCoins,
            mutate storage,
            mutate auction,
            isAuctionComplete,
        );
        return;
    }

    var myBalance = contract.getOriginalBalance();

    if (isAuctionComplete && !isAuctionNull) {
        val parsedHeader = lazy MessageHeader.fromSlice(in.body);

        val balanceBeforeMsg = myBalance - in.valueCoins;

        var amountToSend = balanceBeforeMsg;
        val available = balanceBeforeMsg - MIN_TONS_FOR_STORAGE;

        if (amountToSend > available) {
            amountToSend = available;
        }

        if (amountToSend > 0) {
            val refundMsg = createMessage({
                body: FillUp { queryId: parsedHeader.queryId },
                bounce: false,
                dest: storage.collectionAddress,
                value: amountToSend,
            });
            refundMsg.send(SEND_MODE_IGNORE_ERRORS);

            // since messages are processed at action phase, we need to manage
            // balance in compute phase runtime ourselves
            myBalance -= amountToSend;
        }

        storage.ownerAddress = auction.maxBidAddress;
        storage.auction = null;
        storage.save();
    }

    var msg = lazy AllowedItemMessage.fromSlice(in.body);

    match (msg) {
        TransferOwnership => {
            assert (in.senderAddress == storage.ownerAddress!) throw ERROR_NOT_OWNER;

            applyOwnershipTransfer(
                myBalance,
                mutate storage,
                msg.queryId,
                msg.transferData,
                in.originalForwardFee,
            );
        }

        EditContent => {
            assert (
                in.senderAddress == storage.ownerAddress!
            ) throw ERROR_ONLY_OWNER_CAN_EDIT_CONTENT;

            storage.content = msg.newContent;
            storage.lastFillUpTime = blockchain.now();
            storage.save();
        }

        ChangeDnsRecord => {
            assert (
                in.senderAddress == storage.ownerAddress!
            ) throw ERROR_ONLY_OWNER_CAN_CHANGE_DNS;

            var dnsRecords = storage.content.load();

            if (msg.value.remainingRefsCount() > 0) {
                dnsRecords.set(msg.key, msg.value.loadRef());
            } else {
                dnsRecords.delete(msg.key);
            }

            storage.content = dnsRecords.toCell();
            storage.lastFillUpTime = blockchain.now();
            storage.save();
        }

        ProcessGovernanceDecision => {
            assert (isAuctionNull) throw ERROR_GOVERNANCE_REQUIRES_NO_AUCTION;

            val configCell = blockchain.configParam(DNS_CONFIG_ID);
            assert (configCell != null) throw ERROR_CONFIG_ENTRY_NOT_FOUND;

            val configDict = loadDnsConfigMap(configCell);

            val configValueLookup = configDict.get(storage.index);
            assert (configValueLookup.isFound) throw ERROR_CONFIG_ENTRY_NOT_FOUND;

            val configValue = configValueLookup.loadValue();
            // no need for lazy here
            val decision = GovernanceDecision.fromSlice(
                configValue,
                { throwIfOpcodeDoesNotMatch: ERROR_CONFIG_OPERATION_INVALID },
            );

            match (decision) {
                GovernanceTransfer => {
                    applyOwnershipTransfer(
                        myBalance,
                        mutate storage,
                        msg.queryId,
                        decision.transferData,
                        in.originalForwardFee,
                    );
                }

                GovernanceRelease => {
                    val fillMsg = createMessage({
                        body: FillUp { queryId: msg.queryId },
                        bounce: false,
                        dest: storage.collectionAddress,
                        value: 0,
                    });
                    // SAFETY: governance release intentionally sends all remaining balance to the collection and destroys this item contract.
                    fillMsg.send(SEND_MODE_CARRY_ALL_BALANCE + SEND_MODE_DESTROY);
                }
            }
        }

        DnsRecordRelease => {
            val now = blockchain.now();

            assert (
                now - storage.lastFillUpTime > ONE_YEAR && isAuctionNull
            ) throw ERROR_DNS_BALANCE_RELEASE_FORBIDDEN;

            val minPrice = getMinPrice(storage.domain.beginParse().remainingBitsCount(), now);
            assert (in.valueCoins >= minPrice) throw ERROR_BID_TOO_LOW;

            val balanceWithoutMsg = myBalance - in.valueCoins;
            val amountToSend = balanceWithoutMsg - MIN_TONS_FOR_STORAGE;

            if (amountToSend > 0) {
                val responseMsg = createMessage({
                    body: DnsRecordRelease { queryId: msg.queryId },
                    bounce: false,
                    dest: storage.ownerAddress!,
                    value: amountToSend,
                });
                responseMsg.send(SEND_MODE_IGNORE_ERRORS);
            }

            storage.ownerAddress = null;
            storage.auction = AuctionState {
                maxBidAddress: in.senderAddress,
                auctionEndTime: now + AUCTION_START_DURATION,
                maxBidAmount: in.valueCoins,
            }.toCell();
            storage.lastFillUpTime = now;

            storage.save();
        }

        GetStaticData => {
            val responseMsg = createMessage({
                body: ReportStaticData {
                    queryId: msg.queryId,
                    itemIndex: storage.index,
                    collectionAddress: storage.collectionAddress,
                },
                bounce: false,
                dest: in.senderAddress,
                value: 0,
            });
            responseMsg.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE);
        }

        else => throw ERROR_UNKNOWN_OP,
    }
}

get fun get_nft_data(): NftDataReply {
    val loading = startLoadingDnsItemStorage();

    if (!loading.isInitialized()) {
        val st = loading.parseNotInitialized();

        return {
            isInitialized: false,
            index: st.index,
            collectionAddress: st.collectionAddress,
            ownerAddress: null,
            content: null,
        };
    }

    val st = loading.parseInitialized();
    return {
        isInitialized: true,
        index: st.index,
        collectionAddress: st.collectionAddress,
        ownerAddress: st.ownerAddress,
        content: st.content,
    };
}

get fun get_editor(): address? {
    val loading = startLoadingDnsItemStorage();

    if (!loading.isInitialized()) {
        return null;
    }

    val st = loading.parseInitialized();
    return st.ownerAddress;
}

get fun get_domain(): slice {
    // this will panic if storage is not init, but so does FunC impl
    val st = startLoadingDnsItemStorage().parseInitialized();
    return st.domain.beginParse();
}

get fun get_auction_info(): AuctionState {
    val st = startLoadingDnsItemStorage().parseInitialized();

    return st.unpackAuction().1;
}

get fun get_last_fill_up_time(): int {
    val st = startLoadingDnsItemStorage().parseInitialized();
    return st.lastFillUpTime;
}

get fun dnsresolve(subdomain: slice, category: uint256): DnsResolveResponse {
    val subdomainBits = subdomain.remainingBitsCount();
    assert (subdomainBits % BYTE_SIZE == 0) throw ERROR_DNS_INVALID_SUBDOMAIN_BITS;

    val st = startLoadingDnsItemStorage().parseInitialized();

    val dnsRecord = st.content.load();

    val startsWithZeroByte = subdomain.preloadInt(BYTE_SIZE) == 0;
    assert (startsWithZeroByte) throw ERROR_GOVERNANCE_REQUIRES_NO_AUCTION;

    if (subdomainBits > BYTE_SIZE) {
        category = "dns_next_resolver".toBase256();
    }

    if (category == 0) {
        return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: dnsRecord.toLowLevelDict() };
    }

    val value = dnsRecord.get(category);
    if (!value.isFound) {
        return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: null };
    }

    return { resolvedPrefixLengthBits: BYTE_SIZE, resolvedRecord: value.loadValue() };
}

import "dns-utils"
import "errors"
import "messages"
import "storage"

fun processBidOrTopUp(
    senderAddress: address,
    valueCoins: coins,
    mutate st: ItemStorageInitialized,
    mutate auction: AuctionState,
    auctionComplete: bool,
) {
    if (auctionComplete) {
        assert (senderAddress == st.ownerAddress!) throw ERROR_ONLY_OWNER_CAN_FILL_UP_AFTER_AUCTION;

        st.lastFillUpTime = blockchain.now();
        st.save();
    } else {
        // 5% greater than previous bid
        assert (valueCoins >= mulDivFloor(auction.maxBidAmount, 105, 100)) throw ERROR_BID_TOO_LOW;

        val myBalance = contract.getOriginalBalance();

        var amountToSend = auction.maxBidAmount;
        val available = myBalance - MIN_TONS_FOR_STORAGE;

        if (amountToSend > available) {
            amountToSend = available;
        }

        if (amountToSend > 0) {
            val outbidMsg = createMessage({
                body: OutbidNotification { queryId: blockchain.logicalTime() },
                bounce: false,
                dest: auction.maxBidAddress!, // safe null cast since previous bid exists
                value: amountToSend,
            });
            outbidMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
        }

        auction.maxBidAmount = valueCoins;
        auction.maxBidAddress = senderAddress;

        val deltaTime = AUCTION_PROLONGATION - (auction.auctionEndTime - blockchain.now());
        if (deltaTime > 0) {
            auction.auctionEndTime += deltaTime;
        }

        st.auction = auction.toCell();
        st.lastFillUpTime = blockchain.now();
        st.save();
    }
}

fun address.forceBasechain(self) {
    assert (self.getWorkchain() == BASECHAIN) throw ERROR_WRONG_WORKCHAIN;
}

@inline
fun applyOwnershipTransfer(
    myBalance: coins,
    mutate storage: ItemStorageInitialized,
    queryId: uint64,
    transferData: TransferOwnershipData,
    fwdFees: coins,
) {
    val newOwnerAddress = transferData.newOwnerAddress;
    newOwnerAddress.forceBasechain();

    val responseDestination = transferData.responseDestination;
    val forwardAmount = transferData.forwardAmount;

    var restAmount = myBalance - MIN_TONS_FOR_STORAGE;
    if (forwardAmount > 0) {
        restAmount -= (forwardAmount + fwdFees);
    }

    val needResponse = responseDestination != null;
    if (needResponse) {
        restAmount -= fwdFees;
    }

    // all Tolk numeric types are int at runtime
    // so even when type is coins, this assert is not useless
    assert (restAmount >= 0) throw ERROR_NOT_ENOUGH_BALANCE;

    if (forwardAmount > 0) {
        val responseMsg = createMessage({
            body: OwnershipAssigned {
                queryId,
                oldOwnerAddress: storage.ownerAddress,
                payload: transferData.forwardPayload,
            },
            bounce: false,
            dest: newOwnerAddress,
            value: forwardAmount,
        });
        responseMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
    }

    if (needResponse) {
        responseDestination!.forceBasechain();

        val excessesMsg = createMessage({
            body: Excesses { queryId },
            bounce: false,
            dest: responseDestination!,
            value: restAmount,
        });
        excessesMsg.send(SEND_MODE_PAY_FEES_SEPARATELY);
    }

    storage.ownerAddress = newOwnerAddress;
    storage.lastFillUpTime = blockchain.now();
    storage.save();
}

import "errors"

const ONE_MONTH = 60 * 60 * 24 * 30
const ONE_YEAR = 60 * 60 * 24 * 366

const AUCTION_START_TIME = 1659171600 // GMT: Monday, 30 July 2022 г., 09:00:00
const AUCTION_START_DURATION = 60 * 60 * 24 * 7
const AUCTION_END_DURATION = 60 * 60
const AUCTION_PROLONGATION = 60 * 60

const MIN_TONS_FOR_STORAGE = ton("1")
const ONE_TON = ton("1")

// https://github.com/ton-blockchain/ton/blob/7e3df93ca2ab336716a230fceb1726d81bac0a06/crypto/block/block.tlb#L819
const DNS_NEXT_RESOLVER_PREFIX = 0xba93
const BYTE_SIZE = 8
const DNS_CONFIG_ID = 80

const TON_WWW_DOMAIN_SIZE = 8 // "ton.www" (6) + 2 null-encoding symbols
const TON_DOMAIN_SIZE = 4 // "ton" (3) + 1 null-encoding symbol
const TELEGRAM_DOMAIN_SIZE = 5 // "t.me" (3) + 2 null-encoding symbols
const MIN_DOMAIN_SIZE = 3
const MAX_DOMAIN_SIZE = 126

fun address.toNextResolver(self): cell {
    return beginCell().storeUint(DNS_NEXT_RESOLVER_PREFIX, 16).storeAddress(self).endCell();
}

// Snake-like domain in remaining bits/refs.
// "ab".ref("cd").ref("ef") -> "abcdef"
fun readDomainFromComment(mutate inMsgBody: slice): slice {
    var result = beginCell();

    result.storeSlice(inMsgBody.loadBits(inMsgBody.remainingBitsCount()));

    repeat (inMsgBody.depth()) {
        val refsLen = inMsgBody.remainingRefsCount();
        assert (refsLen == 1) throw ERROR_DOMAIN_FORMAT_INVALID;
        inMsgBody = inMsgBody.loadRef().beginParse();
        result.storeSlice(inMsgBody.loadBits(inMsgBody.remainingBitsCount()));
    }

    return result.toSlice();
}

// "ton\0test\0" -> "ton"
fun getTopDomainBits(domain: slice): int {
    var bytes = domain;

    var bits = 0;
    var shouldStop = false;

    while (!shouldStop) {
        // we do not check domain.length because it MUST contain \0 character
        val ch = bytes.loadUint(BYTE_SIZE);

        shouldStop = ch == 0;

        if (!shouldStop) {
            bits += BYTE_SIZE;
        }
    }

    // matches original FunC exit code
    assert (bits > 0) throw ERROR_DOMAIN_TOO_LONG;
    return bits;
}

enum DomainChar {
    Hyphen = 45      // ASCII '-': allowed only inside a label, not as the first/last checked char.
    DigitZero = 48   // ASCII '0': lower bound for allowed digits
    DigitNine = 57   // ASCII '9': upper bound for allowed digits
    LowercaseA = 97  // ASCII 'a': lower bound for allowed lowercase letters
    LowercaseZ = 122 // ASCII 'z': upper bound for allowed lowercase letters
}

@inline_ref
fun checkDomainString(domain: slice, len: int): bool {
    var bytes = domain;
    var i = 0;

    val charCount = len / BYTE_SIZE;
    val lastChar = charCount - 1;

    repeat (charCount) {
        val ch = bytes.loadUint(BYTE_SIZE);

        val isDigit = ch >= (DomainChar.DigitZero as int) && ch <= (DomainChar.DigitNine as int);
        val isLowercaseLetter = ch >= (DomainChar.LowercaseA as int) &&
        ch <= (DomainChar.LowercaseZ as int);

        var valid = isDigit || isLowercaseLetter;
        if (!valid) {
            valid = ch == (DomainChar.Hyphen as int) && i > 0 && i < lastChar;
        }

        if (!valid) {
            return false;
        }

        i += 1;
    }

    return true;
}

struct MinPriceConfig {
    startMinPrice: int
    endMinPrice: int
}

fun getMinPriceConfig(domainCharCount: int): MinPriceConfig {
    var res = MinPriceConfig {
        startMinPrice: 10,
        endMinPrice: 1,
    };

    if (domainCharCount == 4) {
        res = { startMinPrice: 1000, endMinPrice: 100 };
    }
    if (domainCharCount == 5) {
        res = { startMinPrice: 500, endMinPrice: 50 };
    }
    if (domainCharCount == 6) {
        res = { startMinPrice: 400, endMinPrice: 40 };
    }
    if (domainCharCount == 7) {
        res = { startMinPrice: 300, endMinPrice: 30 };
    }
    if (domainCharCount == 8) {
        res = { startMinPrice: 200, endMinPrice: 20 };
    }
    if (domainCharCount == 9) {
        res = { startMinPrice: 100, endMinPrice: 10 };
    }
    if (domainCharCount == 10) {
        res = { startMinPrice: 50, endMinPrice: 5 };
    }

    return res;
}

fun getMinPrice(domainBitsLength: int, nowTime: int): int {
    val config = getMinPriceConfig(domainBitsLength / BYTE_SIZE);
    var startMinPrice = config.startMinPrice * ONE_TON;
    val endMinPrice = config.endMinPrice * ONE_TON;

    val seconds = nowTime - AUCTION_START_TIME;
    val months = seconds / ONE_MONTH;

    var res: int;

    if (months > 21) {
        res = endMinPrice;
    } else {
        repeat (months) {
            // -10% each passing month
            startMinPrice = startMinPrice * 90 / 100;
        }

        res = startMinPrice;
    }

    return res;
}

